WITH valid AS (SELECT id, customer_id, browser, started_at, country, INITCAP(TRIM(device)) AS device_title, COALESCE(browser, 'OTHER') AS browser_clean FROM sessions WHERE started_at >= TIMESTAMP '2023-09-14 05:00:00' AND browser IS NOT NULL) SELECT id, customer_id, browser, started_at, ROW_NUMBER() OVER (PARTITION BY browser, country ORDER BY started_at DESC, id ASC) AS event_seq, FIRST_VALUE(country, TRUE) OVER (PARTITION BY country ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id ASC) AS seq_no FROM valid;
